+	ClassDB::bind_method(D_METHOD("set_radius_top", "radius_top"), &TaperedCapsuleMesh::set_radius_top);
+	ClassDB::bind_method(D_METHOD("get_radius_top"), &TaperedCapsuleMesh::get_radius_top);
