+		d["radius_bottom"] = bottom_radius;
+		d["height"] = mid_height;
+	} else {
+		d["radius"] = (top_radius + bottom_radius) / 2.0;
+		d["height"] = get_height();
+		WARN_PRINT_ONCE("Tapered capsule shapes aren't supported by the current physics engine. They might behave as regular capsules in the mean time.");

